svg.script:
var found = {};
var total = 7;
function foundDiff(id) {
  if (found[id]) return;
  found[id] = true;
  var ra = document.getElementById('ring_'+id+'_a');
  var rb = document.getElementById('ring_'+id+'_b');
  ra.setAttribute('opacity','1'); ra.classList.add('pulseRing');
  rb.setAttribute('opacity','1'); rb.classList.add('pulseRing');
  var count = Object.keys(found).length;
  document.getElementById('counterText').textContent = 'تم اكتشاف: ' + count + ' / ' + total;
  if (count === total) {
    document.getElementById('winMsg').setAttribute('opacity','1');
    document.getElementById('winMsg').classList.add('winPop');
  }
}
